proxy.on("connect", (req, cliente, cabeza) => {
  const [host, puerto] = req.url.split(":");          // lo único que pidió el cliente
  console.log(`CONNECT  ${req.url}`);
  const destino = net.connect(+puerto, HOSTS[host] || host, () => {
    cliente.write("HTTP/1.1 200 Connection Established\r\n\r\n");
    if (cabeza.length) destino.write(cabeza);
    cliente.pipe(destino); destino.pipe(cliente);      // copia ciega en los dos sentidos
  });
  /* … más abajo registra el primer mensaje del cliente y lee el SNI … */
});

server {
  listen 48570;
  location /api/ {
    proxy_pass http://127.0.0.1:48571;              # servicio api
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-For $remote_addr;  # quién es el cliente de verdad
    proxy_set_header X-Forwarded-Proto $scheme;     # http o https
  }
  location / { proxy_pass http://127.0.0.1:48572; /* igual, hacia web */ }
}
server {
  listen 48573 ssl;  server_name api.ejemplo.test;
  ssl_certificate     cadena.pem;   # hoja + intermedia de la CA de práctica
  ssl_certificate_key hoja.key;
  location / { proxy_pass http://127.0.0.1:48571; /* … */ }
}
